declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use App\Core\Database;use App\Services\LiveDisplaySessionService;$pdo=Database::connection();$token=trim((string)($_GET['token']??''));$s=LiveDisplaySessionService::byToken($pdo,$token);if(!$s){http_response_code(404);exit;}$test=$s['data_mode']==='test';$rt=$test?'bdc_test_scoring_rounds':'bdc_scoring_rounds';$et=$test?'bdc_test_events':'bdc_events';$q=$pdo->prepare("SELECT r.division,r.round_type,e.name event_name FROM {$rt} r JOIN {$et} e ON e.id=r.event_id WHERE r.id=:r AND e.id=:e");$q->execute(['r'=>$s['current_round_id'],'e'=>(int)($s['active_event_id']??$s['event_id'])]);$r=$q->fetch()?:['event_name'=>'BDC','division'=>'','round_type'=>'final'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;background:#000;color:#fff;font-family:Arial,sans-serif;overflow:hidden}.stage{width:100vw;height:100vh;background:radial-gradient(circle at top,#4a101e,#111827 50%,#030509);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.event{font-size:clamp(24px,2vw,48px);font-weight:900}.meta{margin-top:.5em;color:#ffb7c3;font-size:clamp(14px,1vw,24px)}.title{margin-top:1em;font-size:clamp(36px,4vw,86px);font-weight:900}.ready{margin-top:.8em;font-size:clamp(18px,1.5vw,34px);color:#cbd5e1;letter-spacing:.15em}</style></head><body><div class="stage"><div class="event"><?=e($r['event_name'])?></div><div class="meta"><?=e(strtoupper(str_replace('_',' ',$r['division'])))?> · <?=e(strtoupper($r['round_type']))?></div><div class="title">WINNER REVEAL</div><div class="ready">THE PODIUM AWAITS</div></div></body></html>
